describe('Field Validation Error Display', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should display specific validation error for each invalid field', () => {
    // Intercept the API call to submit the form
    cy.intercept('POST', '/api/form-submit').as('formSubmit');

    // Fill in the first field with valid data
    cy.get('[data-testid="first-name-input"]').type('John');

    // Fill in the second field with invalid data (empty string)
    cy.get('[data-testid="last-name-input"]').type('');

    // Fill in the third field with valid data
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');

    // Fill in the fourth field with invalid data (too short)
    cy.get('[data-testid="password-input"]').type('123');

    // Fill in the fifth field with valid data
    cy.get('[data-testid="confirm-password-input"]').type('123');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API response
    cy.wait('@formSubmit');

    // Verify error messages are displayed for invalid fields
    cy.get('[data-testid="first-name-error"]').should('be.visible').should('contain', 'This field is required');
    cy.get('[data-testid="last-name-error"]').should('be.visible').should('contain', 'This field is required');
    cy.get('[data-testid="email-error"]').should('be.visible').should('contain', 'Please enter a valid email address');
    cy.get('[data-testid="password-error"]').should('be.visible').should('contain', 'Password must be at least 8 characters long');

    // Verify success message is displayed for valid fields
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Form submitted successfully');

    // Verify form is cleared after submission
    cy.get('[data-testid="first-name-input"]').should('have.value', '');
    cy.get('[data-testid="last-name-input"]').should('have.value', '');
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="password-input"]').should('have.value', '');
  });

  it('should display validation error when all fields are empty', () => {
    // Fill in all fields with empty values
    cy.get('[data-testid="first-name-input"]').type('');
    cy.get('[data-testid="last-name-input"]').type('');
    cy.get('[data-testid="email-input"]').type('');
    cy.get('[data-testid="password-input"]').type('');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API response
    cy.wait('@formSubmit');

    // Verify error messages are displayed for all fields
    cy.get('[data-testid="first-name-error"]').should('be.visible').should('contain', 'This field is required');
    cy.get('[data-testid="last-name-error"]').should('be.visible').should('contain', 'This field is required');
    cy.get('[data-testid="email-error"]').should('be.visible').should('contain', 'This field is required');
    cy.get('[data-testid="password-error"]').should('be.visible').should('contain', 'This field is required');

    // Verify success message is not displayed
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify form is cleared after submission
    cy.get('[data-testid="first-name-input"]').should('have.value', '');
    cy.get('[data-testid="last-name-input"]').should('have.value', '');
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="password-input"]').should('have.value', '');
  });
});
